($h=0$ does not support stationary solutions)
	\label{obs:10}
The equation
	\begin{equation}
	\label{110}
	\varphi''-\varphi+2|\varphi|^2 \varphi +i \alpha \varphi=0,
	\end{equation}
	\underline{does not have}  non-trivial classical solutions $\varphi_\alpha$.

\label{102}
Let $\alpha_0$ is such that $ 0<\alpha_0<\f{\dpr{1}{\varphi_0}}{\|\varphi_0\|^2}$. Then, there exists $h_0=h_0(\alpha_0)>0$, so that for every $h: 0<h<h_0$ and $\alpha:=\alpha_0 h$, there exists a stationary solution $\varphi_{\alpha}=\varphi_{\alpha,1}+i \varphi_{\alpha,2}$ of
\eqref{1.1}  or equivalently  solutions $\varphi_{\alpha,1}(h), \varphi_{\alpha,2}(h)$ of the profile system   \eqref{150}. Moreover, there is the following Taylor expansions formula for the coefficients
\begin{eqnarray}
\label{500}
\varphi_{\alpha,1} &=& (a_0+\f{b_0}{2} h D_2^0+O(h^2))  \varphi_0+h \Psi_1^0 +O_{\{\varphi_0\}^\perp}(h^2)\\
\label{510}
\varphi_{\alpha,2} &=&  (b_0-\f{a_0}{2} h D_2^0+O(h^2))  \varphi_0+h \Psi_2^0 +O_{\{\varphi_0\}^\perp}(h^2)
\end{eqnarray}
where
\begin{eqnarray*}
	& & a_0=\sigma_0  \f{\|\varphi_0\|^2}{\dpr{1}{\varphi_0}}, \ \ \ b_0= \alpha_0  \f{\|\varphi_0\|^2} {\dpr{1}{\varphi_0}},
	\sigma_0=  \pm \sqrt{ \f{\dpr{1}{\varphi_0}^2}{\|\varphi_0\|^4}-\alpha_0^2}; \\
		& & D_2^0 = 8 \f{\dpr{\varphi_0^2 L_+^{-1}[1]}{L_-^{-1}[b_0-\alpha_0 \varphi_0]}}{\dpr{1}{\varphi_0}}; \\
	& &  \Psi_1^0=  a_0^2 L_+^{-1}[1]  + b_0 L_-^{-1}[b_0-\alpha_0\varphi_0];  \\
	& & \Psi_2^0=  a_0 b_0  L_+^{-1}[1]  - a_0 L_-^{-1}[b_0-\alpha_0\varphi_0].
\end{eqnarray*}

 \label{prop:h0}
 The solution $\varphi_0$, (which can be written explicitly by taking $h=0$ in \eqref{20}) satisfies
 \begin{itemize}
 \item ${\mathcal L}_{-,0}\geq 0$, with ${\mathcal L}_{-,0}[\varphi_0]=0$, ${\mathcal L}_{-,0}|_{\{\varphi_0\}^\perp}>0$
 \item $n({\mathcal L}_{+,0})=1$, ${\mathcal L}_{+,0}[\varphi'_0]=0$, $0$ is a simple eigenvalue for ${\mathcal L}_{+,0}$.
 \end{itemize}
 In addition,   the following two relations hold
$$
\dpr{{\mathcal L}_{+,0}^{-1} \varphi_0}{\varphi_0}<0, \ \ \dpr{{\mathcal L}_{+,0}^{-1}[1]}{\varphi_0}=0
$$

\label{le:10}
There exists $h_0>0$, so that for all $|h|<h_0$, we have the following formulas
\begin{eqnarray}
\label{25}
\varphi_h &=& \varphi_0 + h {\mathcal L}_{+,0}^{-1}[1]+O(h^2),  \\
\label{27}
 \lambda_0({\mathcal L}_{-,h}) &=& \f{\int_{0}^{T} \varphi_0(x)dx}{\int_{0}^{T} \varphi_0^2 (x)dx} h+O(h^2)\\
 \label{28}
 \tilde{\varphi}_h &=& \varphi_0+  {\mathcal L}_{-,0}^{-1}\left[4 \varphi_0^2  {\mathcal L}_{+,0}^{-1}[1] + \f{\int_{0}^{T} \varphi_0(x)dx}{\int_{0}^{T} \varphi_0^2 (x)dx}     \varphi_0 \right] h +O(h^2),
\end{eqnarray}
where\footnote{The quantity $\left(4 \varphi_0^2  {\mathcal L}_{+,0}^{-1}[1] + \f{\int_{0}^{T} \varphi_0(x)dx}{\int_{0}^{T} \varphi_0^2 (x)dx}     \varphi_0\right)  \perp \varphi_0$, whence ${\mathcal L}_{-,0}^{-1}$ is well-defined}  $\tilde{\varphi}_h:  {\mathcal L}_{-,h}[\tilde{\varphi}_h]= \lambda_0({\mathcal L}_{-,h}) \tilde{\varphi}_h$ is the  ground state of
${\mathcal L}_{-,h}$.
In particular, ${\mathcal L}_{-,h}>0$ for $0<h<<1$.

